import re

ANSI = re.compile(r'\x1b\[[0-9;]*[A-Za-z]')
SEC = re.compile(r'^section_(?P<kind>start|end):(?P<ts>\d+):(?P<name>[A-Za-z0-9_.\-]+)(?:\[[^\]]*\])?\x1b?\[0K(?P<title>.*)$')
RUN = re.compile(r'^Running with gitlab-runner (?P<version>\S+)(?:\s+\((?P<revision>[^)]+)\))?\s*$')
ON = re.compile(r'^\s+on (?P<runner>\S+)(?: (?P<token>[^\s,]+))?(?:, system ID: (?P<sysid>\S+))?\s*$')
RES = re.compile(r'^(?:ERROR: )?Job (?P<status>failed|succeeded)(?:: (?P<reason>.*))?\s*$')

def clean(s):
    return ANSI.sub('', s).replace('\r', '').rstrip()

def parse(lines):
    runner = {}
    runner_lines = []
    secs = []
    sec_lines = []
    open_secs = {}
    log = []
    log_lines = []
    result = {}
    result_lines = []
    cur = ''
    for i, raw in enumerate(lines):
        if not raw.strip():
            continue
        m = SEC.match(raw.replace('\r', ''))
        if m:
            name = m.group('name')
            ts = int(m.group('ts'))
            if m.group('kind') == 'start':
                rec = {'Section': name, 'Start': ts, 'End': None, 'Duration': None, 'Title': clean(m.group('title'))}
                secs.append(rec)
                open_secs[name] = rec
                cur = name
            else:
                rec = open_secs.get(name)
                if rec is None:
                    rec = {'Section': name, 'Start': None, 'End': ts, 'Duration': None, 'Title': ''}
                    secs.append(rec)
                else:
                    rec['End'] = ts
                    if rec['Start'] is not None:
                        rec['Duration'] = ts - rec['Start']
                cur = ''
            sec_lines.append(i)
            continue
        s = clean(raw)
        m = RUN.match(s)
        if m:
            runner['Runner version'] = m.group('version')
            if m.group('revision'):
                runner['Revision'] = m.group('revision')
            runner_lines.append(i)
            continue
        m = ON.match(s)
        if m and runner_lines and not log:
            runner['Runner'] = m.group('runner')
            if m.group('token'):
                runner['Token'] = m.group('token')
            if m.group('sysid'):
                runner['System ID'] = m.group('sysid')
            runner_lines.append(i)
            continue
        m = RES.match(s)
        if m:
            result['Status'] = m.group('status')
            if m.group('reason'):
                result['Reason'] = m.group('reason')
            result_lines.append(i)
            continue
        if s.startswith('$ '):
            log.append({'Section': cur, 'Type': 'command', 'Text': s[2:]})
        else:
            log.append({'Section': cur, 'Type': 'output', 'Text': s})
        log_lines.append(i)
    blocks = []
    if runner:
        blocks.append({'name': 'runner', 'kind': 'kv', 'lines': runner_lines, 'records': [runner]})
    if secs:
        blocks.append({'name': 'sections', 'kind': 'table', 'lines': sec_lines, 'records': secs})
    if log:
        blocks.append({'name': 'log', 'kind': 'table', 'lines': log_lines, 'records': log})
    if result:
        blocks.append({'name': 'result', 'kind': 'kv', 'lines': result_lines, 'records': [result]})
    return {'blocks': blocks, 'skip': []}
